from fastapi import APIRouter, FastAPI
from fastapi.testclient import TestClient


def test_strict_slashes_false_matches_both_forms():
    app = FastAPI()
    router = APIRouter(strict_slashes=False)

    @router.get("/users")
    def read_users() -> dict[str, str]:
        return {"users": "data"}

    app.include_router(router)
    client = TestClient(app)

    response = client.get("/users", follow_redirects=False)
    assert response.status_code == 200
    assert response.json() == {"users": "data"}

    response = client.get("/users/", follow_redirects=False)
    assert response.status_code == 200
    assert response.json() == {"users": "data"}


def test_strict_slashes_true_default_redirects_or_404():
    app = FastAPI()
    router = APIRouter(strict_slashes=True)

    @router.get("/users2")
    def read_users2() -> dict[str, str]:
        return {"users2": "data"}

    app.include_router(router)
    client = TestClient(app)

    response = client.get("/users2", follow_redirects=False)
    assert response.status_code == 200
    assert response.json() == {"users2": "data"}

    response = client.get("/users2/", follow_redirects=False)
    assert response.status_code in (307, 404)


def test_strict_slashes_default_router_matches_only_canonical():
    app = FastAPI()
    router = APIRouter()  # default strict_slashes=True

    @router.get("/users3")
    def read_users3() -> dict[str, str]:
        return {"users3": "data"}

    app.include_router(router)
    client = TestClient(app)

    response = client.get("/users3", follow_redirects=False)
    assert response.status_code == 200

    response = client.get("/users3/", follow_redirects=False)
    assert response.status_code in (307, 404)


def test_strict_slashes_false_propagates_to_route():
    router = APIRouter(strict_slashes=False)

    @router.get("/items")
    def read_items() -> dict[str, list[str]]:
        return {"items": []}

    assert len(router.routes) == 1
    route = router.routes[0]
    assert isinstance(route, type(router.routes[0]))
    assert route.strict_slashes is False
    assert route.path_regex.match("/items") is not None
    assert route.path_regex.match("/items/") is not None


def test_strict_slashes_true_default_on_route():
    router = APIRouter(strict_slashes=True)

    @router.get("/things")
    def read_things() -> dict[str, list[str]]:
        return {"things": []}

    assert router.routes[0].strict_slashes is True
    assert router.routes[0].path_regex.match("/things") is not None
    assert router.routes[0].path_regex.match("/things/") is None

